  "settings.refMaintTagOscillationNote": "對相同作品上的相同標籤寫入相反修補程式的兩條規則，會以 tag_patch_conflict 暫緩這兩個候選項目，而不是讓最後執行的規則勝出。新增標籤的規則與在稍後執行中移除標籤的另一條規則無法以這種方式被捕獲：這是一種撰寫錯誤，會使標籤永遠來回翻轉，因此請調整兩者的範圍使其無法同時符合條件。",
